head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS26700.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_2);
    var array_grid = [grd_List];
    setResizeGrid(array_grid, 150);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {
    //ins_combo_set(dts_BAS_SECU_KIND_CD, vScrenID, SCREN_PROCS_TP_CD_01 ,"03426","ALL"); //기초증권종류 

};

/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var sToday = $c.ut.cGetToday2();
    edt_FROM_BZ_DD.setValue($c.ut.cGetPlusDate2($c.ut.cGetMinusYear(sToday, 1), 1));
    edt_TO_BZ_DD.setValue(sToday);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_List.removeAll();
};


/**
 * 일반상품(금) 조회
 */
scwin.ins_search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(true);
    btn_search.src = "../img/btn_select_d.gif";
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.down.select.listStdCdGoldDownLoadInquiry" + "&outputMessageId=INS_LIST_STDCD_GOLD_DOWNLOAD_INQUIRY" + "&{P}BZ_DD_FROM=" + $c.stf.getObjectValue(edt_FROM_BZ_DD) + "&{P}BZ_DD_TO=" + $c.stf.getObjectValue(edt_TO_BZ_DD) + "&{P}HALT_YN=" + $c.stf.getObjectValue(cmb_HALT_YN);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function() {
    // 영업일 필수
    if ($c.stf.getObjectValue(edt_FROM_BZ_DD) == "") {
        $c.win.alert("영업 시작일을 입력하세요.");
        edt_FROM_BZ_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_TO_BZ_DD) == "") {
        $c.win.alert("영업 종료일을 입력하세요.");
        edt_TO_BZ_DD.focus();
        return false;
    }

    // 영업일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_BZ_DD, edt_TO_BZ_DD) == false) {
        return false;
    }

    // 1년 이내 체크.
    if (($c.stf.getObjectValue(edt_FROM_BZ_DD) != "" && $c.stf.getObjectValue(edt_TO_BZ_DD) != "") &&
        (eval($c.ut.cGetPlusYear(edt_FROM_BZ_DD.getValue(), 1)) < eval(edt_TO_BZ_DD.getValue()))) {
        $c.win.alert("영업일의 검색 기간은 1년 이내로만 가능합니다.");
        edt_FROM_BZ_DD.focus();
        return false;
    }
    return true;
};


/**
 * 체크박스 체크 시 그리드 항목 show
 */
scwin.fn_GridCtrl = function(pObj) {
    var sColId = pObj.id;
    sColId = sColId.replace("chb_", "");
    var bChecked = $c.stf.getObjectValue(pObj);
    if (bChecked == "Y" && $c.cm.getColumnProp(grd_List, sColId, "Show") != "TRUE") {
        $c.cm.setColumnProp(grd_List, sColId, "Show", true);
    } else if (bChecked == "N" && $c.cm.getColumnProp(grd_List, sColId, "Show") == "TRUE") {
        $c.cm.setColumnProp(grd_List, sColId, "Show", false);
    }
    //grd_List.AutoResizeAllCol(true);

};




/**
 * 전체선택 체크 시 나머지 모두 언체크.
 */
scwin.fn_AllUnCheck = function() {
    var sAllChecked = $c.stf.getObjectValue(chb_ALL);
    var oCheckBoxs = document.getElementsByName("chk");
    for (var nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].setValue((sAllChecked == "Y") ? true : false);
        scwin.fn_GridCtrl(oCheckBoxs[nRow]);
    }
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_List_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_List);
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_List);

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(false);
    btn_search.src = "../img/btn_select.gif";
};
scwin.btn_Excel_onclick = function() {
    if (dts_List.getTotalRow() <= 0) {
        $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 로그 남기고..	
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var title = "일반상품(금)다운로드";
    var xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";
    $c.data.downloadGridViewOffice(grd_List, title, xls_path, 8, 0);
    //grd_List.GridToExcel(title, "", "8");

};
scwin.chb_ALL_onclick = function() {
    // 전체선택
    scwin.fn_AllUnCheck();
};
scwin.chb_ISU_SRT_CD_onclick = function() {
    scwin.fn_GridCtrl(chb_ISU_SRT_CD);
};
scwin.chb_ISU_KOR_NM_onclick = function() {
    scwin.fn_GridCtrl(chb_ISU_KOR_NM);
};
scwin.chb_ISU_ENG_NM_onclick = function() {
    scwin.fn_GridCtrl(chb_ISU_ENG_NM);
};
scwin.chb_PURITY_onclick = function() {
    scwin.fn_GridCtrl(chb_PURITY);
};
scwin.chb_WEIGHT_onclick = function() {
    scwin.fn_GridCtrl(chb_WEIGHT);
};
scwin.chb_DELIST_DD_onclick = function() {
    scwin.fn_GridCtrl(chb_DELIST_DD);
};
scwin.chb_HALT_YN_onclick = function() {
    scwin.fn_GridCtrl(chb_HALT_YN);
};
scwin.img_FROM_BZ_DD_onclick = function() {
    popUpCalendar2(edt_FROM_BZ_DD);
};
scwin.img_TO_BZ_DD_onclick = function() {
    popUpCalendar2(edt_TO_BZ_DD);
};
